function countGapTriples(arr: number[], a: number, b: number, c: number): number {
  const V = 1001, n = arr.length;
  const pre = new Array(V + 1).fill(0); // pre[v + 1] = how many earlier values are ≤ v
  let count = 0;
  for (let j = 0; j < n; j++) {
    for (let k = j + 1; k < n; k++) {
      if (Math.abs(arr[j] - arr[k]) > b) continue;
      const lo = Math.max(0, arr[j] - a, arr[k] - c);
      const hi = Math.min(V - 1, arr[j] + a, arr[k] + c);
      if (lo <= hi) count += pre[hi + 1] - pre[lo];
    }
    for (let v = arr[j]; v < V; v++) pre[v + 1]++; // arr[j] becomes an earlier value
  }
  return count;
}

